IF ISJSON(@Seed) <> 1 THROW 51001, 'Invalid seed JSON', 1;
DECLARE @Changes TABLE (Entity nvarchar(40) PRIMARY KEY, Added int NOT NULL);

BEGIN TRY
    BEGIN TRANSACTION;
    DECLARE @LockResult int;
    EXEC @LockResult = sys.sp_getapplock @Resource=N'SOOPI_DEMO_CATALOG_IMPORT',
        @LockMode='Exclusive', @LockOwner='Transaction', @LockTimeout=15000;
    IF @LockResult < 0 THROW 51002, 'Another catalog import is running', 1;

    SELECT MaLK,SoLuongTon,SoLuongDaGiu,DonGiaVon,DonGiaDichVu,DinhMucTonToiThieu,KeChinh,PhienBan
    INTO #StockBefore FROM LinhKien WITH (HOLDLOCK);

    SELECT s.code AS SourceCode,COALESCE(e.MaNhom,s.code) AS Code,s.name AS Name,s.sortOrder AS SortOrder
    INTO #Groups
    FROM OPENJSON(@Seed,'$.groups') WITH (code nvarchar(30),name nvarchar(100),sortOrder int) s
    LEFT JOIN NhomThietBi e WITH (UPDLOCK,HOLDLOCK) ON e.TenNhom=s.name;
    IF EXISTS(SELECT 1 FROM #Groups s JOIN NhomThietBi e ON e.MaNhom=s.Code WHERE e.TenNhom<>s.Name)
        THROW 51003, 'Category code conflicts with existing data', 1;
    INSERT NhomThietBi(MaNhom,TenNhom,ThuTu,HoatDong)
    SELECT Code,Name,SortOrder,1 FROM #Groups s WHERE NOT EXISTS(SELECT 1 FROM NhomThietBi e WHERE e.MaNhom=s.Code);
    INSERT @Changes VALUES(N'Categories',@@ROWCOUNT);

    SELECT s.code AS SourceCode,COALESCE(e.MaLoai,s.code) AS Code,g.Code AS GroupCode,
        s.name AS Name,s.identifier AS Identifier,s.profile AS Profile
    INTO #Types
    FROM OPENJSON(@Seed,'$.types') WITH
        (code nvarchar(30),[group] nvarchar(30),name nvarchar(100),identifier nvarchar(10),profile nvarchar(30)) s
    JOIN #Groups g ON g.SourceCode=s.[group]
    OUTER APPLY(SELECT TOP(1) MaLoai FROM LoaiThietBi WITH(UPDLOCK,HOLDLOCK)
        WHERE MaNhom=g.Code AND TenLoai=s.name ORDER BY MaLoai) e;
    IF EXISTS(SELECT 1 FROM #Types s JOIN LoaiThietBi e ON e.MaLoai=s.Code
        WHERE e.MaNhom<>s.GroupCode OR e.TenLoai<>s.Name OR e.LoaiDinhDanh<>s.Identifier)
        THROW 51004, 'Device type code conflicts with existing data', 1;
    INSERT LoaiThietBi(MaLoai,MaNhom,TenLoai,LoaiDinhDanh,ChecklistChanDoan,HoatDong)
    SELECT Code,GroupCode,Name,Identifier,
        N'["Kiểm tra ngoại quan","Kiểm tra nguồn và kết nối","Kiểm tra chức năng chính","Kiểm tra an toàn sau sửa chữa"]',1
    FROM #Types s WHERE NOT EXISTS(SELECT 1 FROM LoaiThietBi e WHERE e.MaLoai=s.Code);
    INSERT @Changes VALUES(N'DeviceTypes',@@ROWCOUNT);

    SELECT s.code AS SourceCode,COALESCE(e.MaHang,s.code) AS Code,s.name AS Name
    INTO #Brands FROM OPENJSON(@Seed,'$.brands') WITH(code nvarchar(30),name nvarchar(100)) s
    LEFT JOIN HangSanXuat e WITH(UPDLOCK,HOLDLOCK) ON e.TenHang=s.name;
    IF EXISTS(SELECT 1 FROM #Brands s JOIN HangSanXuat e ON e.MaHang=s.Code WHERE e.TenHang<>s.Name)
        THROW 51005, 'Manufacturer code conflicts with existing data', 1;
    INSERT HangSanXuat(MaHang,TenHang,HoatDong)
    SELECT Code,Name,1 FROM #Brands s WHERE NOT EXISTS(SELECT 1 FROM HangSanXuat e WHERE e.MaHang=s.Code);
    INSERT @Changes VALUES(N'Brands',@@ROWCOUNT);

    SELECT s.code AS SourceCode,COALESCE(e.MaSP,s.code) AS Code,s.name AS Name,b.Code AS BrandCode,
        b.Name AS BrandName,COALESCE(e.MaLoai,t.Code) AS TypeCode,
        COALESCE(existingType.MaNhom,t.GroupCode) AS GroupCode,t.Profile
    INTO #Products
    FROM OPENJSON(@Seed,'$.products') WITH
        (code nvarchar(30),name nvarchar(150),brand nvarchar(30),type nvarchar(30)) s
    JOIN #Brands b ON b.SourceCode=s.brand JOIN #Types t ON t.SourceCode=s.type
    LEFT JOIN SanPham e WITH(UPDLOCK,HOLDLOCK) ON e.MaHang=b.Code AND e.TenSP=s.name
    LEFT JOIN LoaiThietBi existingType ON existingType.MaLoai=e.MaLoai;
    IF (SELECT COUNT(*) FROM #Products)<>(SELECT COUNT(*) FROM OPENJSON(@Seed,'$.products'))
        THROW 51006, 'Missing product reference', 1;
    IF EXISTS(SELECT 1 FROM #Products s JOIN SanPham e ON e.MaSP=s.Code WHERE e.MaHang<>s.BrandCode OR e.TenSP<>s.Name)
        THROW 51007, 'Product code conflicts with existing data', 1;
    -- tempdb on the VPS uses a different collation from the application DB.
    CREATE TABLE #NewProducts(Code nvarchar(30) COLLATE DATABASE_DEFAULT PRIMARY KEY);
    INSERT SanPham(MaSP,TenSP,MaHang,MaLoai,DongSanPham,ThoiHanBaoHanhMacDinhThang,HoatDong)
    OUTPUT inserted.MaSP INTO #NewProducts
    SELECT Code,Name,BrandCode,TypeCode,NULL,12,1 FROM #Products s
    WHERE NOT EXISTS(SELECT 1 FROM SanPham e WHERE e.MaSP=s.Code);
    INSERT @Changes VALUES(N'Products',@@ROWCOUNT);

    INSERT HangSanXuat_NhomThietBi(MaHang,MaNhom)
    SELECT DISTINCT BrandCode,GroupCode FROM #Products s
    WHERE NOT EXISTS(SELECT 1 FROM HangSanXuat_NhomThietBi e WITH(UPDLOCK,HOLDLOCK)
        WHERE e.MaHang=s.BrandCode AND e.MaNhom=s.GroupCode);
    INSERT @Changes VALUES(N'BrandCategories',@@ROWCOUNT);

    SELECT s.code AS SourceCode,COALESCE(e.MaNCC,s.code) AS Code,s.name AS Name,s.email AS Email,
        ROW_NUMBER() OVER(ORDER BY s.code) AS Seq
    INTO #Suppliers FROM OPENJSON(@Seed,'$.suppliers') WITH
        (code nvarchar(30),name nvarchar(150),email nvarchar(100)) s
    OUTER APPLY(SELECT TOP(1) MaNCC FROM NhaCungCap WITH(UPDLOCK,HOLDLOCK) WHERE TenNCC=s.name ORDER BY MaNCC) e;
    IF EXISTS(SELECT 1 FROM #Suppliers s JOIN NhaCungCap e ON e.MaNCC=s.Code WHERE e.TenNCC<>s.Name)
        THROW 51008, 'Supplier code conflicts with existing data', 1;
    INSERT NhaCungCap(MaNCC,TenNCC,SDT,DiaChi,Email,HoatDong)
    SELECT Code,Name,NULL,NULL,Email,1
    FROM #Suppliers s WHERE NOT EXISTS(SELECT 1 FROM NhaCungCap e WHERE e.MaNCC=s.Code);
    INSERT @Changes VALUES(N'Suppliers',@@ROWCOUNT);

    SELECT N'DM-LK-'+RIGHT(p.SourceCode,16)+N'-'+CONVERT(nvarchar(2),t.number) AS Code,
        t.name+N' - '+p.Name AS Name,p.GroupCode,p.BrandName,s.Code AS SupplierCode,
        CAST(ROUND((t.price+ABS(CAST(CHECKSUM(p.SourceCode) AS bigint))%6*25000)*0.65,-3) AS decimal(18,2)) AS Cost,
        CAST(t.price+ABS(CAST(CHECKSUM(p.SourceCode) AS bigint))%6*25000 AS decimal(18,2)) AS Price
    INTO #Parts FROM #Products p
    JOIN OPENJSON(@Seed,'$.partTemplates') WITH
        (profile nvarchar(30),number int,name nvarchar(80),price decimal(18,2)) t ON t.profile=p.Profile
    JOIN #Suppliers s ON s.Seq=ABS(CAST(CHECKSUM(p.SourceCode) AS bigint))%(SELECT COUNT(*) FROM #Suppliers)+1;
    IF (SELECT COUNT(*) FROM #Parts)<>4*(SELECT COUNT(*) FROM #Products)
        THROW 51009, 'Every model must have four sample components', 1;
    IF EXISTS(SELECT 1 FROM #Parts WHERE LEN(Name)>150 OR Cost<0 OR Price<Cost)
        THROW 51010, 'Invalid sample component data', 1;
    IF EXISTS(SELECT 1 FROM #Parts s JOIN LinhKien e ON e.MaLK=s.Code WHERE e.TenLK<>s.Name OR ISNULL(e.TenHang,N'')<>s.BrandName)
        THROW 51011, 'Component code conflicts with existing data', 1;
    CREATE TABLE #NewParts(Code nvarchar(30) COLLATE DATABASE_DEFAULT PRIMARY KEY);
    INSERT LinhKien(MaLK,TenLK,DonViTinh,MaNhom,TenHang,DonGiaVon,DonGiaDichVu,
        SoLuongTon,SoLuongDaGiu,DinhMucTonToiThieu,KeChinh,ThoiHanBaoHanhThang,MaNCC,HoatDong,PhienBan)
    OUTPUT inserted.MaLK INTO #NewParts
    SELECT Code,Name,N'Cái',GroupCode,BrandName,Cost,Price,0,0,0,N'KHO-D-01-01',3,SupplierCode,1,0
    FROM #Parts s WHERE NOT EXISTS(SELECT 1 FROM LinhKien e WITH(UPDLOCK,HOLDLOCK)
        WHERE e.MaLK=s.Code OR (e.TenLK=s.Name AND e.MaNhom=s.GroupCode AND e.TenHang=s.BrandName));
    INSERT @Changes VALUES(N'Parts',@@ROWCOUNT);
    INSERT TonKhoTheoKe(MaLK,MaKe,SoLuong)
    SELECT Code,N'KHO-D-01-01',0 FROM #NewParts;

    SELECT N'DM-DV-'+g.SourceCode+N'-'+CONVERT(nvarchar(2),s.number) AS Code,
        s.name+N' - '+g.Name AS Name,g.Code AS GroupCode,s.price AS Price
    INTO #Services FROM #Groups g CROSS APPLY OPENJSON(@Seed,'$.services') WITH
        (number int,name nvarchar(80),price decimal(18,2)) s;
    IF EXISTS(SELECT 1 FROM #Services WHERE LEN(Code)>30 OR LEN(Name)>150 OR Price<0)
        THROW 51012, 'Invalid sample service data', 1;
    IF EXISTS(SELECT 1 FROM #Services s JOIN BangGiaDichVu e ON e.MaDichVu=s.Code WHERE e.TenDichVu<>s.Name OR e.MaNhom<>s.GroupCode)
        THROW 51013, 'Service code conflicts with existing data', 1;
    INSERT BangGiaDichVu(MaDichVu,TenDichVu,MaNhom,DonGia,HoatDong)
    SELECT Code,Name,GroupCode,Price,1 FROM #Services s
    WHERE NOT EXISTS(SELECT 1 FROM BangGiaDichVu e WITH(UPDLOCK,HOLDLOCK)
        WHERE e.MaDichVu=s.Code OR (e.MaNhom=s.GroupCode AND e.TenDichVu=s.Name));
    INSERT @Changes VALUES(N'Services',@@ROWCOUNT);

    -- Product-scoped sample policies only for models created in this transaction.
    -- No new brand-wide policy can affect existing devices or warranty decisions.
    INSERT ChinhSachBaoHanh(MaChinhSach,PhamVi,MaSP,MaHang,TenChinhSach,SoThangBaoHanh,
        DieuKienBaoHanh,TruongHopTuChoi,NhaPhanPhoi,HoatDong)
    SELECT N'DM-BH-'+RIGHT(p.SourceCode,16),N'PRODUCT',p.Code,p.BrandCode,
        N'Bảo hành 12 tháng - '+p.Name,12,
        N'Áp dụng cho lỗi kỹ thuật trong thời hạn bảo hành. Đối chiếu số định danh, tình trạng tem và chứng từ tiếp nhận.',
        N'Không áp dụng với hư hỏng do va đập, chất lỏng, tự ý can thiệp hoặc quá thời hạn bảo hành.',
        N'Trung tâm dịch vụ Soopi',1
    FROM #Products p JOIN #NewProducts n ON n.Code=p.Code
    WHERE NOT EXISTS(SELECT 1 FROM ChinhSachBaoHanh e WITH(UPDLOCK,HOLDLOCK) WHERE e.MaChinhSach=N'DM-BH-'+RIGHT(p.SourceCode,16));
    INSERT @Changes VALUES(N'WarrantyPolicies',@@ROWCOUNT);

    IF EXISTS(SELECT MaLK,SoLuongTon,SoLuongDaGiu,DonGiaVon,DonGiaDichVu,DinhMucTonToiThieu,KeChinh,PhienBan FROM #StockBefore
        EXCEPT SELECT p.MaLK,p.SoLuongTon,p.SoLuongDaGiu,p.DonGiaVon,p.DonGiaDichVu,p.DinhMucTonToiThieu,p.KeChinh,p.PhienBan
        FROM LinhKien p JOIN #StockBefore b ON b.MaLK=p.MaLK)
        THROW 51014, 'Existing stock or prices were modified', 1;
    IF EXISTS(SELECT 1 FROM LinhKien p JOIN #NewParts n ON n.Code=p.MaLK
        WHERE p.SoLuongTon<>0 OR p.SoLuongDaGiu<>0 OR p.DinhMucTonToiThieu<>0
            OR ISNULL((SELECT SUM(k.SoLuong) FROM TonKhoTheoKe k WHERE k.MaLK=p.MaLK),-1)<>0)
        THROW 51015, 'New components must have zero stock and reservations', 1;

    SELECT Entity,Added FROM @Changes ORDER BY Entity;
    IF @Apply=1
    BEGIN
        IF EXISTS(SELECT 1 FROM @Changes WHERE Added>0)
        BEGIN
            DECLARE @Summary nvarchar(500);
            SELECT @Summary=STRING_AGG(CONVERT(nvarchar(max),Entity+N':'+CONVERT(nvarchar(12),Added)),N'; ') FROM @Changes;
            INSERT NhatKyThaoTac(ThoiGian,MaNguoiThaoTac,TenNguoiThaoTac,VaiTro,HanhDong,NhanHanhDong,LoaiDoiTuong,MaDoiTuong,GiaTriTruoc,GiaTriSau)
            VALUES(CONVERT(datetime2(0),SYSDATETIMEOFFSET() AT TIME ZONE 'SE Asia Standard Time'),
                N'OPERATOR_IMPORT',N'Nhập danh mục mẫu theo yêu cầu',N'ADMINISTRATIVE_IMPORT',
                N'CATALOG_BULK_IMPORTED',N'Nhập bổ sung danh mục mẫu',N'CATALOG',N'DEMO-CATALOG-20261105',NULL,@Summary);
        END;
        COMMIT TRANSACTION;
        SELECT N'COMMITTED' AS ImportResult;
    END
    ELSE
    BEGIN
        ROLLBACK TRANSACTION;
        SELECT N'PREVIEW_ROLLED_BACK' AS ImportResult;
    END;
END TRY
BEGIN CATCH
    IF @@TRANCOUNT>0 ROLLBACK TRANSACTION;
    THROW;
END CATCH;
